const _astro_dataLayerContent = [["Map",1,2,9,10],"meta::meta",["Map",3,4,5,6,7,8],"astro-version","5.14.5","content-config-digest","c96d0655b8ceab56","astro-config-digest","{\"root\":{},\"srcDir\":{},\"publicDir\":{},\"outDir\":{},\"cacheDir\":{},\"site\":\"https://luisbonilla90.github.io\",\"compressHTML\":true,\"base\":\"/\",\"trailingSlash\":\"ignore\",\"output\":\"static\",\"scopedStyleStrategy\":\"attribute\",\"build\":{\"format\":\"directory\",\"client\":{},\"server\":{},\"assets\":\"assets\",\"assetsPrefix\":\"\",\"serverEntry\":\"entry.mjs\",\"redirects\":true,\"inlineStylesheets\":\"auto\",\"concurrency\":1},\"server\":{\"open\":false,\"host\":false,\"port\":4321,\"streaming\":true,\"allowedHosts\":[]},\"redirects\":{},\"image\":{\"endpoint\":{\"route\":\"/_image\"},\"service\":{\"entrypoint\":\"astro/assets/services/sharp\",\"config\":{}},\"domains\":[],\"remotePatterns\":[],\"responsiveStyles\":false},\"devToolbar\":{\"enabled\":true},\"markdown\":{\"syntaxHighlight\":{\"type\":\"shiki\",\"excludeLangs\":[\"math\"]},\"shikiConfig\":{\"langs\":[],\"langAlias\":{},\"theme\":\"github-dark\",\"themes\":{},\"wrap\":false,\"transformers\":[]},\"remarkPlugins\":[],\"rehypePlugins\":[],\"remarkRehype\":{},\"gfm\":true,\"smartypants\":true},\"i18n\":{\"defaultLocale\":\"en\",\"locales\":[\"en\",\"es\"],\"routing\":{\"prefixDefaultLocale\":false,\"redirectToDefaultLocale\":false,\"fallbackType\":\"redirect\"}},\"security\":{\"checkOrigin\":true,\"allowedDomains\":[]},\"env\":{\"schema\":{},\"validateSecrets\":false},\"experimental\":{\"clientPrerender\":false,\"contentIntellisense\":false,\"headingIdCompat\":false,\"preserveScriptOrder\":false,\"liveContentCollections\":false,\"csp\":false,\"staticImportMetaEnv\":false,\"chromeDevtoolsWorkspace\":false,\"failOnPrerenderConflict\":false},\"legacy\":{\"collections\":false}}","blog",["Map",11,12,118,119,198,199],"modern-javascript-clean-code",{id:11,data:13,body:31,filePath:32,digest:33,rendered:34,legacyId:117},{title:14,description:15,pubDate:16,author:17,tags:18,lang:24,draft:25,jsonLd:26},"Modern JavaScript: Clean Code Principles and Best Practices","Discover essential clean code principles and best practices for writing maintainable, scalable JavaScript applications.",["Date","2024-10-05T00:00:00.000Z"],"Luis Bonilla",[19,20,21,22,23],"javascript","clean-code","best-practices","software-engineering","code-quality","en",false,{type:27,headline:14,description:15,author:28,datePublished:30},"BlogPosting",{type:29,name:17},"Person","2024-10-05","# Modern JavaScript: Clean Code Principles and Best Practices\n\n**Clean code in JavaScript means writing code that is easy to read, understand, and maintain through consistent naming conventions, single-purpose functions, and clear structure**. Following clean code principles reduces bugs by up to 40% and improves team productivity by making code more maintainable and testable (Source: Code Complete, Steve McConnell).\n\nWriting clean, maintainable JavaScript code is essential for building scalable applications. This guide explores fundamental principles and practical techniques for improving code quality.\n\n## Clean Code Principles\n\n### 1. Single Responsibility Principle (SRP)\n\nEach function or class should have one clear purpose:\n\n```javascript\n// Bad: Multiple responsibilities\nfunction processUserData(user) {\n  validateUser(user);\n  saveToDatabase(user);\n  sendEmail(user);\n  generateReport(user);\n}\n\n// Good: Single responsibility\nfunction validateUser(user) {\n  // Only validation logic\n  if (!user.email) throw new Error('Email required');\n  if (!user.name) throw new Error('Name required');\n  return true;\n}\n\nfunction saveUser(user) {\n  // Only database logic\n  return database.users.create(user);\n}\n\nfunction notifyUser(user) {\n  // Only notification logic\n  return emailService.send(user.email, 'Welcome!');\n}\n```\n\n### 2. Descriptive Naming\n\nUse clear, intention-revealing names:\n\n```javascript\n// Bad\nconst d = new Date();\nconst x = users.filter(u => u.a);\n\n// Good\nconst currentDate = new Date();\nconst activeUsers = users.filter(user => user.isActive);\n```\n\n### 3. Pure Functions\n\nWrite functions without side effects:\n\n```javascript\n// Impure: Modifies external state\nlet total = 0;\nfunction addToTotal(value) {\n  total += value;\n  return total;\n}\n\n// Pure: No side effects\nfunction calculateTotal(currentTotal, value) {\n  return currentTotal + value;\n}\n```\n\n## Modern JavaScript Features\n\n### Optional Chaining\n\nSafely access nested properties:\n\n```javascript\n// Before\nconst street = user && user.address && user.address.street;\n\n// After\nconst street = user?.address?.street;\n```\n\n### Nullish Coalescing\n\nProvide default values only for null/undefined:\n\n```javascript\n// Before (falsy values like 0 or '' would trigger default)\nconst count = value || 10;\n\n// After (only null/undefined trigger default)\nconst count = value ?? 10;\n```\n\n### Destructuring with Defaults\n\nExtract values with fallback defaults:\n\n```javascript\nconst { \n  name = 'Anonymous',\n  age = 0,\n  city = 'Unknown'\n} = user;\n```\n\n### Array Methods\n\nUse functional array methods for cleaner code:\n\n```javascript\n// Map: Transform each element\nconst userNames = users.map(user => user.name);\n\n// Filter: Select elements based on condition\nconst adults = users.filter(user => user.age >= 18);\n\n// Reduce: Aggregate values\nconst totalAge = users.reduce((sum, user) => sum + user.age, 0);\n\n// Find: Get first matching element\nconst admin = users.find(user => user.role === 'admin');\n```\n\n## Error Handling\n\n### Try-Catch with Async/Await\n\n```javascript\nasync function fetchUserData(userId) {\n  try {\n    const response = await fetch(`/api/users/${userId}`);\n    \n    if (!response.ok) {\n      throw new Error(`HTTP error! status: ${response.status}`);\n    }\n    \n    const data = await response.json();\n    return data;\n  } catch (error) {\n    console.error('Failed to fetch user:', error);\n    throw error;\n  }\n}\n```\n\n### Custom Error Classes\n\n```javascript\nclass ValidationError extends Error {\n  constructor(message, field) {\n    super(message);\n    this.name = 'ValidationError';\n    this.field = field;\n  }\n}\n\nfunction validateEmail(email) {\n  if (!email.includes('@')) {\n    throw new ValidationError('Invalid email format', 'email');\n  }\n}\n```\n\n## Code Organization\n\n### Module Pattern\n\nOrganize code into reusable modules:\n\n```javascript\n// userService.js\nexport class UserService {\n  constructor(apiClient) {\n    this.apiClient = apiClient;\n  }\n\n  async getUser(id) {\n    return this.apiClient.get(`/users/${id}`);\n  }\n\n  async updateUser(id, data) {\n    return this.apiClient.put(`/users/${id}`, data);\n  }\n}\n\n// main.js\nimport { UserService } from './userService.js';\n\nconst userService = new UserService(apiClient);\nconst user = await userService.getUser(123);\n```\n\n### Dependency Injection\n\nInject dependencies for better testability:\n\n```javascript\n// Good: Dependencies injected\nclass ThemeManager {\n  constructor(storage, uiAdapter) {\n    this.storage = storage;\n    this.uiAdapter = uiAdapter;\n  }\n\n  applyTheme(theme) {\n    this.storage.save(theme);\n    this.uiAdapter.update(theme);\n  }\n}\n\n// Easy to test with mocks\nconst mockStorage = { save: jest.fn() };\nconst mockUI = { update: jest.fn() };\nconst manager = new ThemeManager(mockStorage, mockUI);\n```\n\n## Performance Optimization\n\n### Debouncing\n\nLimit function execution frequency:\n\n```javascript\nfunction debounce(func, delay) {\n  let timeoutId;\n  return function (...args) {\n    clearTimeout(timeoutId);\n    timeoutId = setTimeout(() => func.apply(this, args), delay);\n  };\n}\n\n// Usage\nconst searchHandler = debounce((query) => {\n  fetchSearchResults(query);\n}, 300);\n\ninput.addEventListener('input', (e) => searchHandler(e.target.value));\n```\n\n### Memoization\n\nCache expensive computations:\n\n```javascript\nfunction memoize(fn) {\n  const cache = new Map();\n  \n  return function (...args) {\n    const key = JSON.stringify(args);\n    \n    if (cache.has(key)) {\n      return cache.get(key);\n    }\n    \n    const result = fn.apply(this, args);\n    cache.set(key, result);\n    return result;\n  };\n}\n\nconst expensiveCalculation = memoize((n) => {\n  // Complex computation\n  return n * n;\n});\n```\n\n## Testing Best Practices\n\n### Write Testable Code\n\n```javascript\n// Testable function\nexport function calculateDiscount(price, discountPercent) {\n  if (price < 0 || discountPercent < 0 || discountPercent > 100) {\n    throw new Error('Invalid input');\n  }\n  return price * (1 - discountPercent / 100);\n}\n\n// Test\ntest('calculates 20% discount correctly', () => {\n  expect(calculateDiscount(100, 20)).toBe(80);\n});\n```\n\n## Best Practices Checklist\n\n- [ ] Functions follow Single Responsibility Principle\n- [ ] Variable and function names are descriptive\n- [ ] Code is DRY (Don't Repeat Yourself)\n- [ ] Functions are pure when possible\n- [ ] Error handling is comprehensive\n- [ ] Code is properly documented\n- [ ] Dependencies are injected\n- [ ] Tests cover critical functionality\n- [ ] Performance is optimized where needed\n- [ ] Code follows consistent style guide\n\n## Conclusion\n\nClean code is not just about making code work—it's about making code that's easy to read, maintain, and extend. By following these principles and practices, you'll write JavaScript that stands the test of time.\n\nRemember: Code is read far more often than it's written. Invest time in making it clean.\n\n---\n\n**About the Author**: Luis Bonilla is a Software Engineer and Technical Lead with 15+ years of experience building scalable applications and mentoring development teams.","src/content/blog/modern-javascript-clean-code.md","5c60aca82aa4009f",{html:35,metadata:36},"<h1 id=\"modern-javascript-clean-code-principles-and-best-practices\">Modern JavaScript: Clean Code Principles and Best Practices</h1>\n<p><strong>Clean code in JavaScript means writing code that is easy to read, understand, and maintain through consistent naming conventions, single-purpose functions, and clear structure</strong>. Following clean code principles reduces bugs by up to 40% and improves team productivity by making code more maintainable and testable (Source: Code Complete, Steve McConnell).</p>\n<p>Writing clean, maintainable JavaScript code is essential for building scalable applications. This guide explores fundamental principles and practical techniques for improving code quality.</p>\n<h2 id=\"clean-code-principles\">Clean Code Principles</h2>\n<h3 id=\"1-single-responsibility-principle-srp\">1. Single Responsibility Principle (SRP)</h3>\n<p>Each function or class should have one clear purpose:</p>\n<pre class=\"astro-code github-dark\" style=\"background-color:#24292e;color:#e1e4e8; overflow-x: auto;\" tabindex=\"0\" data-language=\"javascript\"><code><span class=\"line\"><span style=\"color:#6A737D\">// Bad: Multiple responsibilities</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">function</span><span style=\"color:#B392F0\"> processUserData</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#FFAB70\">user</span><span style=\"color:#E1E4E8\">) {</span></span>\n<span class=\"line\"><span style=\"color:#B392F0\">  validateUser</span><span style=\"color:#E1E4E8\">(user);</span></span>\n<span class=\"line\"><span style=\"color:#B392F0\">  saveToDatabase</span><span style=\"color:#E1E4E8\">(user);</span></span>\n<span class=\"line\"><span style=\"color:#B392F0\">  sendEmail</span><span style=\"color:#E1E4E8\">(user);</span></span>\n<span class=\"line\"><span style=\"color:#B392F0\">  generateReport</span><span style=\"color:#E1E4E8\">(user);</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">}</span></span>\n<span class=\"line\"></span>\n<span class=\"line\"><span style=\"color:#6A737D\">// Good: Single responsibility</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">function</span><span style=\"color:#B392F0\"> validateUser</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#FFAB70\">user</span><span style=\"color:#E1E4E8\">) {</span></span>\n<span class=\"line\"><span style=\"color:#6A737D\">  // Only validation logic</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">  if</span><span style=\"color:#E1E4E8\"> (</span><span style=\"color:#F97583\">!</span><span style=\"color:#E1E4E8\">user.email) </span><span style=\"color:#F97583\">throw</span><span style=\"color:#F97583\"> new</span><span style=\"color:#B392F0\"> Error</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#9ECBFF\">'Email required'</span><span style=\"color:#E1E4E8\">);</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">  if</span><span style=\"color:#E1E4E8\"> (</span><span style=\"color:#F97583\">!</span><span style=\"color:#E1E4E8\">user.name) </span><span style=\"color:#F97583\">throw</span><span style=\"color:#F97583\"> new</span><span style=\"color:#B392F0\"> Error</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#9ECBFF\">'Name required'</span><span style=\"color:#E1E4E8\">);</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">  return</span><span style=\"color:#79B8FF\"> true</span><span style=\"color:#E1E4E8\">;</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">}</span></span>\n<span class=\"line\"></span>\n<span class=\"line\"><span style=\"color:#F97583\">function</span><span style=\"color:#B392F0\"> saveUser</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#FFAB70\">user</span><span style=\"color:#E1E4E8\">) {</span></span>\n<span class=\"line\"><span style=\"color:#6A737D\">  // Only database logic</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">  return</span><span style=\"color:#E1E4E8\"> database.users.</span><span style=\"color:#B392F0\">create</span><span style=\"color:#E1E4E8\">(user);</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">}</span></span>\n<span class=\"line\"></span>\n<span class=\"line\"><span style=\"color:#F97583\">function</span><span style=\"color:#B392F0\"> notifyUser</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#FFAB70\">user</span><span style=\"color:#E1E4E8\">) {</span></span>\n<span class=\"line\"><span style=\"color:#6A737D\">  // Only notification logic</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">  return</span><span style=\"color:#E1E4E8\"> emailService.</span><span style=\"color:#B392F0\">send</span><span style=\"color:#E1E4E8\">(user.email, </span><span style=\"color:#9ECBFF\">'Welcome!'</span><span style=\"color:#E1E4E8\">);</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">}</span></span></code></pre>\n<h3 id=\"2-descriptive-naming\">2. Descriptive Naming</h3>\n<p>Use clear, intention-revealing names:</p>\n<pre class=\"astro-code github-dark\" style=\"background-color:#24292e;color:#e1e4e8; overflow-x: auto;\" tabindex=\"0\" data-language=\"javascript\"><code><span class=\"line\"><span style=\"color:#6A737D\">// Bad</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">const</span><span style=\"color:#79B8FF\"> d</span><span style=\"color:#F97583\"> =</span><span style=\"color:#F97583\"> new</span><span style=\"color:#B392F0\"> Date</span><span style=\"color:#E1E4E8\">();</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">const</span><span style=\"color:#79B8FF\"> x</span><span style=\"color:#F97583\"> =</span><span style=\"color:#E1E4E8\"> users.</span><span style=\"color:#B392F0\">filter</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#FFAB70\">u</span><span style=\"color:#F97583\"> =></span><span style=\"color:#E1E4E8\"> u.a);</span></span>\n<span class=\"line\"></span>\n<span class=\"line\"><span style=\"color:#6A737D\">// Good</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">const</span><span style=\"color:#79B8FF\"> currentDate</span><span style=\"color:#F97583\"> =</span><span style=\"color:#F97583\"> new</span><span style=\"color:#B392F0\"> Date</span><span style=\"color:#E1E4E8\">();</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">const</span><span style=\"color:#79B8FF\"> activeUsers</span><span style=\"color:#F97583\"> =</span><span style=\"color:#E1E4E8\"> users.</span><span style=\"color:#B392F0\">filter</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#FFAB70\">user</span><span style=\"color:#F97583\"> =></span><span style=\"color:#E1E4E8\"> user.isActive);</span></span></code></pre>\n<h3 id=\"3-pure-functions\">3. Pure Functions</h3>\n<p>Write functions without side effects:</p>\n<pre class=\"astro-code github-dark\" style=\"background-color:#24292e;color:#e1e4e8; overflow-x: auto;\" tabindex=\"0\" data-language=\"javascript\"><code><span class=\"line\"><span style=\"color:#6A737D\">// Impure: Modifies external state</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">let</span><span style=\"color:#E1E4E8\"> total </span><span style=\"color:#F97583\">=</span><span style=\"color:#79B8FF\"> 0</span><span style=\"color:#E1E4E8\">;</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">function</span><span style=\"color:#B392F0\"> addToTotal</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#FFAB70\">value</span><span style=\"color:#E1E4E8\">) {</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  total </span><span style=\"color:#F97583\">+=</span><span style=\"color:#E1E4E8\"> value;</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">  return</span><span style=\"color:#E1E4E8\"> total;</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">}</span></span>\n<span class=\"line\"></span>\n<span class=\"line\"><span style=\"color:#6A737D\">// Pure: No side effects</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">function</span><span style=\"color:#B392F0\"> calculateTotal</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#FFAB70\">currentTotal</span><span style=\"color:#E1E4E8\">, </span><span style=\"color:#FFAB70\">value</span><span style=\"color:#E1E4E8\">) {</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">  return</span><span style=\"color:#E1E4E8\"> currentTotal </span><span style=\"color:#F97583\">+</span><span style=\"color:#E1E4E8\"> value;</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">}</span></span></code></pre>\n<h2 id=\"modern-javascript-features\">Modern JavaScript Features</h2>\n<h3 id=\"optional-chaining\">Optional Chaining</h3>\n<p>Safely access nested properties:</p>\n<pre class=\"astro-code github-dark\" style=\"background-color:#24292e;color:#e1e4e8; overflow-x: auto;\" tabindex=\"0\" data-language=\"javascript\"><code><span class=\"line\"><span style=\"color:#6A737D\">// Before</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">const</span><span style=\"color:#79B8FF\"> street</span><span style=\"color:#F97583\"> =</span><span style=\"color:#E1E4E8\"> user </span><span style=\"color:#F97583\">&#x26;&#x26;</span><span style=\"color:#E1E4E8\"> user.address </span><span style=\"color:#F97583\">&#x26;&#x26;</span><span style=\"color:#E1E4E8\"> user.address.street;</span></span>\n<span class=\"line\"></span>\n<span class=\"line\"><span style=\"color:#6A737D\">// After</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">const</span><span style=\"color:#79B8FF\"> street</span><span style=\"color:#F97583\"> =</span><span style=\"color:#E1E4E8\"> user?.address?.street;</span></span></code></pre>\n<h3 id=\"nullish-coalescing\">Nullish Coalescing</h3>\n<p>Provide default values only for null/undefined:</p>\n<pre class=\"astro-code github-dark\" style=\"background-color:#24292e;color:#e1e4e8; overflow-x: auto;\" tabindex=\"0\" data-language=\"javascript\"><code><span class=\"line\"><span style=\"color:#6A737D\">// Before (falsy values like 0 or '' would trigger default)</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">const</span><span style=\"color:#79B8FF\"> count</span><span style=\"color:#F97583\"> =</span><span style=\"color:#E1E4E8\"> value </span><span style=\"color:#F97583\">||</span><span style=\"color:#79B8FF\"> 10</span><span style=\"color:#E1E4E8\">;</span></span>\n<span class=\"line\"></span>\n<span class=\"line\"><span style=\"color:#6A737D\">// After (only null/undefined trigger default)</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">const</span><span style=\"color:#79B8FF\"> count</span><span style=\"color:#F97583\"> =</span><span style=\"color:#E1E4E8\"> value </span><span style=\"color:#F97583\">??</span><span style=\"color:#79B8FF\"> 10</span><span style=\"color:#E1E4E8\">;</span></span></code></pre>\n<h3 id=\"destructuring-with-defaults\">Destructuring with Defaults</h3>\n<p>Extract values with fallback defaults:</p>\n<pre class=\"astro-code github-dark\" style=\"background-color:#24292e;color:#e1e4e8; overflow-x: auto;\" tabindex=\"0\" data-language=\"javascript\"><code><span class=\"line\"><span style=\"color:#F97583\">const</span><span style=\"color:#E1E4E8\"> { </span></span>\n<span class=\"line\"><span style=\"color:#79B8FF\">  name</span><span style=\"color:#F97583\"> =</span><span style=\"color:#9ECBFF\"> 'Anonymous'</span><span style=\"color:#E1E4E8\">,</span></span>\n<span class=\"line\"><span style=\"color:#79B8FF\">  age</span><span style=\"color:#F97583\"> =</span><span style=\"color:#79B8FF\"> 0</span><span style=\"color:#E1E4E8\">,</span></span>\n<span class=\"line\"><span style=\"color:#79B8FF\">  city</span><span style=\"color:#F97583\"> =</span><span style=\"color:#9ECBFF\"> 'Unknown'</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">} </span><span style=\"color:#F97583\">=</span><span style=\"color:#E1E4E8\"> user;</span></span></code></pre>\n<h3 id=\"array-methods\">Array Methods</h3>\n<p>Use functional array methods for cleaner code:</p>\n<pre class=\"astro-code github-dark\" style=\"background-color:#24292e;color:#e1e4e8; overflow-x: auto;\" tabindex=\"0\" data-language=\"javascript\"><code><span class=\"line\"><span style=\"color:#6A737D\">// Map: Transform each element</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">const</span><span style=\"color:#79B8FF\"> userNames</span><span style=\"color:#F97583\"> =</span><span style=\"color:#E1E4E8\"> users.</span><span style=\"color:#B392F0\">map</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#FFAB70\">user</span><span style=\"color:#F97583\"> =></span><span style=\"color:#E1E4E8\"> user.name);</span></span>\n<span class=\"line\"></span>\n<span class=\"line\"><span style=\"color:#6A737D\">// Filter: Select elements based on condition</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">const</span><span style=\"color:#79B8FF\"> adults</span><span style=\"color:#F97583\"> =</span><span style=\"color:#E1E4E8\"> users.</span><span style=\"color:#B392F0\">filter</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#FFAB70\">user</span><span style=\"color:#F97583\"> =></span><span style=\"color:#E1E4E8\"> user.age </span><span style=\"color:#F97583\">>=</span><span style=\"color:#79B8FF\"> 18</span><span style=\"color:#E1E4E8\">);</span></span>\n<span class=\"line\"></span>\n<span class=\"line\"><span style=\"color:#6A737D\">// Reduce: Aggregate values</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">const</span><span style=\"color:#79B8FF\"> totalAge</span><span style=\"color:#F97583\"> =</span><span style=\"color:#E1E4E8\"> users.</span><span style=\"color:#B392F0\">reduce</span><span style=\"color:#E1E4E8\">((</span><span style=\"color:#FFAB70\">sum</span><span style=\"color:#E1E4E8\">, </span><span style=\"color:#FFAB70\">user</span><span style=\"color:#E1E4E8\">) </span><span style=\"color:#F97583\">=></span><span style=\"color:#E1E4E8\"> sum </span><span style=\"color:#F97583\">+</span><span style=\"color:#E1E4E8\"> user.age, </span><span style=\"color:#79B8FF\">0</span><span style=\"color:#E1E4E8\">);</span></span>\n<span class=\"line\"></span>\n<span class=\"line\"><span style=\"color:#6A737D\">// Find: Get first matching element</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">const</span><span style=\"color:#79B8FF\"> admin</span><span style=\"color:#F97583\"> =</span><span style=\"color:#E1E4E8\"> users.</span><span style=\"color:#B392F0\">find</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#FFAB70\">user</span><span style=\"color:#F97583\"> =></span><span style=\"color:#E1E4E8\"> user.role </span><span style=\"color:#F97583\">===</span><span style=\"color:#9ECBFF\"> 'admin'</span><span style=\"color:#E1E4E8\">);</span></span></code></pre>\n<h2 id=\"error-handling\">Error Handling</h2>\n<h3 id=\"try-catch-with-asyncawait\">Try-Catch with Async/Await</h3>\n<pre class=\"astro-code github-dark\" style=\"background-color:#24292e;color:#e1e4e8; overflow-x: auto;\" tabindex=\"0\" data-language=\"javascript\"><code><span class=\"line\"><span style=\"color:#F97583\">async</span><span style=\"color:#F97583\"> function</span><span style=\"color:#B392F0\"> fetchUserData</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#FFAB70\">userId</span><span style=\"color:#E1E4E8\">) {</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">  try</span><span style=\"color:#E1E4E8\"> {</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">    const</span><span style=\"color:#79B8FF\"> response</span><span style=\"color:#F97583\"> =</span><span style=\"color:#F97583\"> await</span><span style=\"color:#B392F0\"> fetch</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#9ECBFF\">`/api/users/${</span><span style=\"color:#E1E4E8\">userId</span><span style=\"color:#9ECBFF\">}`</span><span style=\"color:#E1E4E8\">);</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">    </span></span>\n<span class=\"line\"><span style=\"color:#F97583\">    if</span><span style=\"color:#E1E4E8\"> (</span><span style=\"color:#F97583\">!</span><span style=\"color:#E1E4E8\">response.ok) {</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">      throw</span><span style=\"color:#F97583\"> new</span><span style=\"color:#B392F0\"> Error</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#9ECBFF\">`HTTP error! status: ${</span><span style=\"color:#E1E4E8\">response</span><span style=\"color:#9ECBFF\">.</span><span style=\"color:#E1E4E8\">status</span><span style=\"color:#9ECBFF\">}`</span><span style=\"color:#E1E4E8\">);</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">    }</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">    </span></span>\n<span class=\"line\"><span style=\"color:#F97583\">    const</span><span style=\"color:#79B8FF\"> data</span><span style=\"color:#F97583\"> =</span><span style=\"color:#F97583\"> await</span><span style=\"color:#E1E4E8\"> response.</span><span style=\"color:#B392F0\">json</span><span style=\"color:#E1E4E8\">();</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">    return</span><span style=\"color:#E1E4E8\"> data;</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  } </span><span style=\"color:#F97583\">catch</span><span style=\"color:#E1E4E8\"> (error) {</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">    console.</span><span style=\"color:#B392F0\">error</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#9ECBFF\">'Failed to fetch user:'</span><span style=\"color:#E1E4E8\">, error);</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">    throw</span><span style=\"color:#E1E4E8\"> error;</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  }</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">}</span></span></code></pre>\n<h3 id=\"custom-error-classes\">Custom Error Classes</h3>\n<pre class=\"astro-code github-dark\" style=\"background-color:#24292e;color:#e1e4e8; overflow-x: auto;\" tabindex=\"0\" data-language=\"javascript\"><code><span class=\"line\"><span style=\"color:#F97583\">class</span><span style=\"color:#B392F0\"> ValidationError</span><span style=\"color:#F97583\"> extends</span><span style=\"color:#B392F0\"> Error</span><span style=\"color:#E1E4E8\"> {</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">  constructor</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#FFAB70\">message</span><span style=\"color:#E1E4E8\">, </span><span style=\"color:#FFAB70\">field</span><span style=\"color:#E1E4E8\">) {</span></span>\n<span class=\"line\"><span style=\"color:#79B8FF\">    super</span><span style=\"color:#E1E4E8\">(message);</span></span>\n<span class=\"line\"><span style=\"color:#79B8FF\">    this</span><span style=\"color:#E1E4E8\">.name </span><span style=\"color:#F97583\">=</span><span style=\"color:#9ECBFF\"> 'ValidationError'</span><span style=\"color:#E1E4E8\">;</span></span>\n<span class=\"line\"><span style=\"color:#79B8FF\">    this</span><span style=\"color:#E1E4E8\">.field </span><span style=\"color:#F97583\">=</span><span style=\"color:#E1E4E8\"> field;</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  }</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">}</span></span>\n<span class=\"line\"></span>\n<span class=\"line\"><span style=\"color:#F97583\">function</span><span style=\"color:#B392F0\"> validateEmail</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#FFAB70\">email</span><span style=\"color:#E1E4E8\">) {</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">  if</span><span style=\"color:#E1E4E8\"> (</span><span style=\"color:#F97583\">!</span><span style=\"color:#E1E4E8\">email.</span><span style=\"color:#B392F0\">includes</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#9ECBFF\">'@'</span><span style=\"color:#E1E4E8\">)) {</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">    throw</span><span style=\"color:#F97583\"> new</span><span style=\"color:#B392F0\"> ValidationError</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#9ECBFF\">'Invalid email format'</span><span style=\"color:#E1E4E8\">, </span><span style=\"color:#9ECBFF\">'email'</span><span style=\"color:#E1E4E8\">);</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  }</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">}</span></span></code></pre>\n<h2 id=\"code-organization\">Code Organization</h2>\n<h3 id=\"module-pattern\">Module Pattern</h3>\n<p>Organize code into reusable modules:</p>\n<pre class=\"astro-code github-dark\" style=\"background-color:#24292e;color:#e1e4e8; overflow-x: auto;\" tabindex=\"0\" data-language=\"javascript\"><code><span class=\"line\"><span style=\"color:#6A737D\">// userService.js</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">export</span><span style=\"color:#F97583\"> class</span><span style=\"color:#B392F0\"> UserService</span><span style=\"color:#E1E4E8\"> {</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">  constructor</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#FFAB70\">apiClient</span><span style=\"color:#E1E4E8\">) {</span></span>\n<span class=\"line\"><span style=\"color:#79B8FF\">    this</span><span style=\"color:#E1E4E8\">.apiClient </span><span style=\"color:#F97583\">=</span><span style=\"color:#E1E4E8\"> apiClient;</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  }</span></span>\n<span class=\"line\"></span>\n<span class=\"line\"><span style=\"color:#F97583\">  async</span><span style=\"color:#B392F0\"> getUser</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#FFAB70\">id</span><span style=\"color:#E1E4E8\">) {</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">    return</span><span style=\"color:#79B8FF\"> this</span><span style=\"color:#E1E4E8\">.apiClient.</span><span style=\"color:#B392F0\">get</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#9ECBFF\">`/users/${</span><span style=\"color:#E1E4E8\">id</span><span style=\"color:#9ECBFF\">}`</span><span style=\"color:#E1E4E8\">);</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  }</span></span>\n<span class=\"line\"></span>\n<span class=\"line\"><span style=\"color:#F97583\">  async</span><span style=\"color:#B392F0\"> updateUser</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#FFAB70\">id</span><span style=\"color:#E1E4E8\">, </span><span style=\"color:#FFAB70\">data</span><span style=\"color:#E1E4E8\">) {</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">    return</span><span style=\"color:#79B8FF\"> this</span><span style=\"color:#E1E4E8\">.apiClient.</span><span style=\"color:#B392F0\">put</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#9ECBFF\">`/users/${</span><span style=\"color:#E1E4E8\">id</span><span style=\"color:#9ECBFF\">}`</span><span style=\"color:#E1E4E8\">, data);</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  }</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">}</span></span>\n<span class=\"line\"></span>\n<span class=\"line\"><span style=\"color:#6A737D\">// main.js</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">import</span><span style=\"color:#E1E4E8\"> { UserService } </span><span style=\"color:#F97583\">from</span><span style=\"color:#9ECBFF\"> './userService.js'</span><span style=\"color:#E1E4E8\">;</span></span>\n<span class=\"line\"></span>\n<span class=\"line\"><span style=\"color:#F97583\">const</span><span style=\"color:#79B8FF\"> userService</span><span style=\"color:#F97583\"> =</span><span style=\"color:#F97583\"> new</span><span style=\"color:#B392F0\"> UserService</span><span style=\"color:#E1E4E8\">(apiClient);</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">const</span><span style=\"color:#79B8FF\"> user</span><span style=\"color:#F97583\"> =</span><span style=\"color:#F97583\"> await</span><span style=\"color:#E1E4E8\"> userService.</span><span style=\"color:#B392F0\">getUser</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#79B8FF\">123</span><span style=\"color:#E1E4E8\">);</span></span></code></pre>\n<h3 id=\"dependency-injection\">Dependency Injection</h3>\n<p>Inject dependencies for better testability:</p>\n<pre class=\"astro-code github-dark\" style=\"background-color:#24292e;color:#e1e4e8; overflow-x: auto;\" tabindex=\"0\" data-language=\"javascript\"><code><span class=\"line\"><span style=\"color:#6A737D\">// Good: Dependencies injected</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">class</span><span style=\"color:#B392F0\"> ThemeManager</span><span style=\"color:#E1E4E8\"> {</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">  constructor</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#FFAB70\">storage</span><span style=\"color:#E1E4E8\">, </span><span style=\"color:#FFAB70\">uiAdapter</span><span style=\"color:#E1E4E8\">) {</span></span>\n<span class=\"line\"><span style=\"color:#79B8FF\">    this</span><span style=\"color:#E1E4E8\">.storage </span><span style=\"color:#F97583\">=</span><span style=\"color:#E1E4E8\"> storage;</span></span>\n<span class=\"line\"><span style=\"color:#79B8FF\">    this</span><span style=\"color:#E1E4E8\">.uiAdapter </span><span style=\"color:#F97583\">=</span><span style=\"color:#E1E4E8\"> uiAdapter;</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  }</span></span>\n<span class=\"line\"></span>\n<span class=\"line\"><span style=\"color:#B392F0\">  applyTheme</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#FFAB70\">theme</span><span style=\"color:#E1E4E8\">) {</span></span>\n<span class=\"line\"><span style=\"color:#79B8FF\">    this</span><span style=\"color:#E1E4E8\">.storage.</span><span style=\"color:#B392F0\">save</span><span style=\"color:#E1E4E8\">(theme);</span></span>\n<span class=\"line\"><span style=\"color:#79B8FF\">    this</span><span style=\"color:#E1E4E8\">.uiAdapter.</span><span style=\"color:#B392F0\">update</span><span style=\"color:#E1E4E8\">(theme);</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  }</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">}</span></span>\n<span class=\"line\"></span>\n<span class=\"line\"><span style=\"color:#6A737D\">// Easy to test with mocks</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">const</span><span style=\"color:#79B8FF\"> mockStorage</span><span style=\"color:#F97583\"> =</span><span style=\"color:#E1E4E8\"> { save: jest.</span><span style=\"color:#B392F0\">fn</span><span style=\"color:#E1E4E8\">() };</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">const</span><span style=\"color:#79B8FF\"> mockUI</span><span style=\"color:#F97583\"> =</span><span style=\"color:#E1E4E8\"> { update: jest.</span><span style=\"color:#B392F0\">fn</span><span style=\"color:#E1E4E8\">() };</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">const</span><span style=\"color:#79B8FF\"> manager</span><span style=\"color:#F97583\"> =</span><span style=\"color:#F97583\"> new</span><span style=\"color:#B392F0\"> ThemeManager</span><span style=\"color:#E1E4E8\">(mockStorage, mockUI);</span></span></code></pre>\n<h2 id=\"performance-optimization\">Performance Optimization</h2>\n<h3 id=\"debouncing\">Debouncing</h3>\n<p>Limit function execution frequency:</p>\n<pre class=\"astro-code github-dark\" style=\"background-color:#24292e;color:#e1e4e8; overflow-x: auto;\" tabindex=\"0\" data-language=\"javascript\"><code><span class=\"line\"><span style=\"color:#F97583\">function</span><span style=\"color:#B392F0\"> debounce</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#FFAB70\">func</span><span style=\"color:#E1E4E8\">, </span><span style=\"color:#FFAB70\">delay</span><span style=\"color:#E1E4E8\">) {</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">  let</span><span style=\"color:#E1E4E8\"> timeoutId;</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">  return</span><span style=\"color:#F97583\"> function</span><span style=\"color:#E1E4E8\"> (</span><span style=\"color:#F97583\">...</span><span style=\"color:#FFAB70\">args</span><span style=\"color:#E1E4E8\">) {</span></span>\n<span class=\"line\"><span style=\"color:#B392F0\">    clearTimeout</span><span style=\"color:#E1E4E8\">(timeoutId);</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">    timeoutId </span><span style=\"color:#F97583\">=</span><span style=\"color:#B392F0\"> setTimeout</span><span style=\"color:#E1E4E8\">(() </span><span style=\"color:#F97583\">=></span><span style=\"color:#E1E4E8\"> func.</span><span style=\"color:#B392F0\">apply</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#79B8FF\">this</span><span style=\"color:#E1E4E8\">, args), delay);</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  };</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">}</span></span>\n<span class=\"line\"></span>\n<span class=\"line\"><span style=\"color:#6A737D\">// Usage</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">const</span><span style=\"color:#79B8FF\"> searchHandler</span><span style=\"color:#F97583\"> =</span><span style=\"color:#B392F0\"> debounce</span><span style=\"color:#E1E4E8\">((</span><span style=\"color:#FFAB70\">query</span><span style=\"color:#E1E4E8\">) </span><span style=\"color:#F97583\">=></span><span style=\"color:#E1E4E8\"> {</span></span>\n<span class=\"line\"><span style=\"color:#B392F0\">  fetchSearchResults</span><span style=\"color:#E1E4E8\">(query);</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">}, </span><span style=\"color:#79B8FF\">300</span><span style=\"color:#E1E4E8\">);</span></span>\n<span class=\"line\"></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">input.</span><span style=\"color:#B392F0\">addEventListener</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#9ECBFF\">'input'</span><span style=\"color:#E1E4E8\">, (</span><span style=\"color:#FFAB70\">e</span><span style=\"color:#E1E4E8\">) </span><span style=\"color:#F97583\">=></span><span style=\"color:#B392F0\"> searchHandler</span><span style=\"color:#E1E4E8\">(e.target.value));</span></span></code></pre>\n<h3 id=\"memoization\">Memoization</h3>\n<p>Cache expensive computations:</p>\n<pre class=\"astro-code github-dark\" style=\"background-color:#24292e;color:#e1e4e8; overflow-x: auto;\" tabindex=\"0\" data-language=\"javascript\"><code><span class=\"line\"><span style=\"color:#F97583\">function</span><span style=\"color:#B392F0\"> memoize</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#FFAB70\">fn</span><span style=\"color:#E1E4E8\">) {</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">  const</span><span style=\"color:#79B8FF\"> cache</span><span style=\"color:#F97583\"> =</span><span style=\"color:#F97583\"> new</span><span style=\"color:#B392F0\"> Map</span><span style=\"color:#E1E4E8\">();</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  </span></span>\n<span class=\"line\"><span style=\"color:#F97583\">  return</span><span style=\"color:#F97583\"> function</span><span style=\"color:#E1E4E8\"> (</span><span style=\"color:#F97583\">...</span><span style=\"color:#FFAB70\">args</span><span style=\"color:#E1E4E8\">) {</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">    const</span><span style=\"color:#79B8FF\"> key</span><span style=\"color:#F97583\"> =</span><span style=\"color:#79B8FF\"> JSON</span><span style=\"color:#E1E4E8\">.</span><span style=\"color:#B392F0\">stringify</span><span style=\"color:#E1E4E8\">(args);</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">    </span></span>\n<span class=\"line\"><span style=\"color:#F97583\">    if</span><span style=\"color:#E1E4E8\"> (cache.</span><span style=\"color:#B392F0\">has</span><span style=\"color:#E1E4E8\">(key)) {</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">      return</span><span style=\"color:#E1E4E8\"> cache.</span><span style=\"color:#B392F0\">get</span><span style=\"color:#E1E4E8\">(key);</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">    }</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">    </span></span>\n<span class=\"line\"><span style=\"color:#F97583\">    const</span><span style=\"color:#79B8FF\"> result</span><span style=\"color:#F97583\"> =</span><span style=\"color:#E1E4E8\"> fn.</span><span style=\"color:#B392F0\">apply</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#79B8FF\">this</span><span style=\"color:#E1E4E8\">, args);</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">    cache.</span><span style=\"color:#B392F0\">set</span><span style=\"color:#E1E4E8\">(key, result);</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">    return</span><span style=\"color:#E1E4E8\"> result;</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  };</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">}</span></span>\n<span class=\"line\"></span>\n<span class=\"line\"><span style=\"color:#F97583\">const</span><span style=\"color:#79B8FF\"> expensiveCalculation</span><span style=\"color:#F97583\"> =</span><span style=\"color:#B392F0\"> memoize</span><span style=\"color:#E1E4E8\">((</span><span style=\"color:#FFAB70\">n</span><span style=\"color:#E1E4E8\">) </span><span style=\"color:#F97583\">=></span><span style=\"color:#E1E4E8\"> {</span></span>\n<span class=\"line\"><span style=\"color:#6A737D\">  // Complex computation</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">  return</span><span style=\"color:#E1E4E8\"> n </span><span style=\"color:#F97583\">*</span><span style=\"color:#E1E4E8\"> n;</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">});</span></span></code></pre>\n<h2 id=\"testing-best-practices\">Testing Best Practices</h2>\n<h3 id=\"write-testable-code\">Write Testable Code</h3>\n<pre class=\"astro-code github-dark\" style=\"background-color:#24292e;color:#e1e4e8; overflow-x: auto;\" tabindex=\"0\" data-language=\"javascript\"><code><span class=\"line\"><span style=\"color:#6A737D\">// Testable function</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">export</span><span style=\"color:#F97583\"> function</span><span style=\"color:#B392F0\"> calculateDiscount</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#FFAB70\">price</span><span style=\"color:#E1E4E8\">, </span><span style=\"color:#FFAB70\">discountPercent</span><span style=\"color:#E1E4E8\">) {</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">  if</span><span style=\"color:#E1E4E8\"> (price </span><span style=\"color:#F97583\">&#x3C;</span><span style=\"color:#79B8FF\"> 0</span><span style=\"color:#F97583\"> ||</span><span style=\"color:#E1E4E8\"> discountPercent </span><span style=\"color:#F97583\">&#x3C;</span><span style=\"color:#79B8FF\"> 0</span><span style=\"color:#F97583\"> ||</span><span style=\"color:#E1E4E8\"> discountPercent </span><span style=\"color:#F97583\">></span><span style=\"color:#79B8FF\"> 100</span><span style=\"color:#E1E4E8\">) {</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">    throw</span><span style=\"color:#F97583\"> new</span><span style=\"color:#B392F0\"> Error</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#9ECBFF\">'Invalid input'</span><span style=\"color:#E1E4E8\">);</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  }</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">  return</span><span style=\"color:#E1E4E8\"> price </span><span style=\"color:#F97583\">*</span><span style=\"color:#E1E4E8\"> (</span><span style=\"color:#79B8FF\">1</span><span style=\"color:#F97583\"> -</span><span style=\"color:#E1E4E8\"> discountPercent </span><span style=\"color:#F97583\">/</span><span style=\"color:#79B8FF\"> 100</span><span style=\"color:#E1E4E8\">);</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">}</span></span>\n<span class=\"line\"></span>\n<span class=\"line\"><span style=\"color:#6A737D\">// Test</span></span>\n<span class=\"line\"><span style=\"color:#B392F0\">test</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#9ECBFF\">'calculates 20% discount correctly'</span><span style=\"color:#E1E4E8\">, () </span><span style=\"color:#F97583\">=></span><span style=\"color:#E1E4E8\"> {</span></span>\n<span class=\"line\"><span style=\"color:#B392F0\">  expect</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#B392F0\">calculateDiscount</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#79B8FF\">100</span><span style=\"color:#E1E4E8\">, </span><span style=\"color:#79B8FF\">20</span><span style=\"color:#E1E4E8\">)).</span><span style=\"color:#B392F0\">toBe</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#79B8FF\">80</span><span style=\"color:#E1E4E8\">);</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">});</span></span></code></pre>\n<h2 id=\"best-practices-checklist\">Best Practices Checklist</h2>\n<ul class=\"contains-task-list\">\n<li class=\"task-list-item\"><input type=\"checkbox\" disabled> Functions follow Single Responsibility Principle</li>\n<li class=\"task-list-item\"><input type=\"checkbox\" disabled> Variable and function names are descriptive</li>\n<li class=\"task-list-item\"><input type=\"checkbox\" disabled> Code is DRY (Don’t Repeat Yourself)</li>\n<li class=\"task-list-item\"><input type=\"checkbox\" disabled> Functions are pure when possible</li>\n<li class=\"task-list-item\"><input type=\"checkbox\" disabled> Error handling is comprehensive</li>\n<li class=\"task-list-item\"><input type=\"checkbox\" disabled> Code is properly documented</li>\n<li class=\"task-list-item\"><input type=\"checkbox\" disabled> Dependencies are injected</li>\n<li class=\"task-list-item\"><input type=\"checkbox\" disabled> Tests cover critical functionality</li>\n<li class=\"task-list-item\"><input type=\"checkbox\" disabled> Performance is optimized where needed</li>\n<li class=\"task-list-item\"><input type=\"checkbox\" disabled> Code follows consistent style guide</li>\n</ul>\n<h2 id=\"conclusion\">Conclusion</h2>\n<p>Clean code is not just about making code work—it’s about making code that’s easy to read, maintain, and extend. By following these principles and practices, you’ll write JavaScript that stands the test of time.</p>\n<p>Remember: Code is read far more often than it’s written. Invest time in making it clean.</p>\n<hr>\n<p><strong>About the Author</strong>: Luis Bonilla is a Software Engineer and Technical Lead with 15+ years of experience building scalable applications and mentoring development teams.</p>",{headings:37,localImagePaths:109,remoteImagePaths:110,frontmatter:111,imagePaths:116},[38,41,45,49,52,55,58,61,64,67,70,73,76,79,82,85,88,91,94,97,100,103,106],{depth:39,slug:40,text:14},1,"modern-javascript-clean-code-principles-and-best-practices",{depth:42,slug:43,text:44},2,"clean-code-principles","Clean Code Principles",{depth:46,slug:47,text:48},3,"1-single-responsibility-principle-srp","1. Single Responsibility Principle (SRP)",{depth:46,slug:50,text:51},"2-descriptive-naming","2. Descriptive Naming",{depth:46,slug:53,text:54},"3-pure-functions","3. Pure Functions",{depth:42,slug:56,text:57},"modern-javascript-features","Modern JavaScript Features",{depth:46,slug:59,text:60},"optional-chaining","Optional Chaining",{depth:46,slug:62,text:63},"nullish-coalescing","Nullish Coalescing",{depth:46,slug:65,text:66},"destructuring-with-defaults","Destructuring with Defaults",{depth:46,slug:68,text:69},"array-methods","Array Methods",{depth:42,slug:71,text:72},"error-handling","Error Handling",{depth:46,slug:74,text:75},"try-catch-with-asyncawait","Try-Catch with Async/Await",{depth:46,slug:77,text:78},"custom-error-classes","Custom Error Classes",{depth:42,slug:80,text:81},"code-organization","Code Organization",{depth:46,slug:83,text:84},"module-pattern","Module Pattern",{depth:46,slug:86,text:87},"dependency-injection","Dependency Injection",{depth:42,slug:89,text:90},"performance-optimization","Performance Optimization",{depth:46,slug:92,text:93},"debouncing","Debouncing",{depth:46,slug:95,text:96},"memoization","Memoization",{depth:42,slug:98,text:99},"testing-best-practices","Testing Best Practices",{depth:46,slug:101,text:102},"write-testable-code","Write Testable Code",{depth:42,slug:104,text:105},"best-practices-checklist","Best Practices Checklist",{depth:42,slug:107,text:108},"conclusion","Conclusion",[],[],{title:14,description:15,pubDate:112,author:17,tags:113,lang:24,draft:25,jsonLd:114},["Date","2024-10-05T00:00:00.000Z"],[19,20,21,22,23],{type:27,headline:14,description:15,author:115,datePublished:30},{type:29,name:17},[],"modern-javascript-clean-code.md","building-accessible-web-applications",{id:118,data:120,body:133,filePath:134,digest:135,rendered:136,legacyId:197},{title:121,description:122,pubDate:123,author:17,tags:124,lang:24,draft:25,jsonLd:130},"Building Accessible Web Applications: A Practical Guide","Learn practical techniques for building web applications that are accessible to all users, including those with disabilities.",["Date","2024-10-10T00:00:00.000Z"],[125,126,127,128,129],"accessibility","a11y","web-development","wcag","inclusive-design",{type:27,headline:121,description:122,author:131,datePublished:132},{type:29,name:17},"2024-10-10","# Building Accessible Web Applications: A Practical Guide\n\n**Web accessibility (a11y) means designing and developing websites that can be used by everyone, including the 15% of the world's population with disabilities (WHO, 2023)**. Accessible web applications follow WCAG (Web Content Accessibility Guidelines) standards to ensure content is perceivable, operable, understandable, and robust for all users, regardless of their abilities or assistive technologies used.\n\nWeb accessibility isn't just a nice-to-have—it's a fundamental requirement for creating inclusive digital experiences. This guide covers practical techniques for building accessible web applications.\n\n## Understanding Web Accessibility\n\nWeb accessibility (a11y) ensures that websites and applications can be used by everyone, including people with:\n\n- Visual impairments\n- Hearing impairments\n- Motor disabilities\n- Cognitive disabilities\n\n## WCAG Guidelines\n\nThe Web Content Accessibility Guidelines (WCAG) provide a framework organized around four principles:\n\n### 1. Perceivable\n\nInformation must be presentable to users in ways they can perceive.\n\n**Example**: Provide text alternatives for images\n\n```html\n<img \n  src=\"chart.png\" \n  alt=\"Sales growth chart showing 25% increase in Q3\"\n/>\n```\n\n### 2. Operable\n\nUser interface components must be operable by all users.\n\n**Example**: Ensure keyboard accessibility\n\n```javascript\n// Good: Keyboard-accessible button\n<button \n  onClick={handleClick}\n  onKeyPress={(e) => e.key === 'Enter' && handleClick()}\n>\n  Submit\n</button>\n```\n\n### 3. Understandable\n\nInformation and interface operation must be understandable.\n\n**Example**: Provide clear error messages\n\n```html\n<input \n  type=\"email\" \n  aria-describedby=\"email-error\"\n  required\n/>\n<span id=\"email-error\" role=\"alert\">\n  Please enter a valid email address\n</span>\n```\n\n### 4. Robust\n\nContent must be robust enough to work with various technologies.\n\n## Practical Accessibility Techniques\n\n### Semantic HTML\n\nUse appropriate HTML elements for their intended purpose:\n\n```html\n<!-- Good -->\n<nav>\n  <ul>\n    <li><a href=\"#home\">Home</a></li>\n    <li><a href=\"#about\">About</a></li>\n  </ul>\n</nav>\n\n<!-- Avoid -->\n<div class=\"nav\">\n  <span onclick=\"navigate()\">Home</span>\n</div>\n```\n\n### ARIA Attributes\n\nUse ARIA attributes to enhance accessibility when semantic HTML isn't sufficient:\n\n```html\n<button \n  aria-label=\"Close dialog\"\n  aria-pressed=\"false\"\n>\n  <span aria-hidden=\"true\">×</span>\n</button>\n```\n\n### Focus Management\n\nEnsure visible focus indicators and logical focus order:\n\n```css\n/* Visible focus indicator */\nbutton:focus-visible {\n  outline: 2px solid #007bff;\n  outline-offset: 2px;\n}\n```\n\n### Color Contrast\n\nMaintain sufficient color contrast (WCAG AA: 4.5:1 for normal text):\n\n```css\n/* Good contrast */\n.text {\n  color: #212529;  /* Dark gray */\n  background: #ffffff;  /* White */\n  /* Contrast ratio: 16.1:1 */\n}\n```\n\n## Testing Accessibility\n\n### Automated Testing\n\nUse tools like:\n- **axe DevTools**: Browser extension for automated testing\n- **Lighthouse**: Built into Chrome DevTools\n- **WAVE**: Web accessibility evaluation tool\n\n### Manual Testing\n\n1. **Keyboard Navigation**: Navigate using only keyboard (Tab, Enter, Escape)\n2. **Screen Reader Testing**: Test with NVDA, JAWS, or VoiceOver\n3. **Zoom Testing**: Test at 200% zoom level\n4. **Color Contrast**: Use contrast checking tools\n\n## Common Accessibility Pitfalls\n\n1. **Missing alt text** on images\n2. **Poor focus management** in modals and dialogs\n3. **Insufficient color contrast**\n4. **Missing form labels**\n5. **Keyboard traps** in interactive components\n6. **Unclear error messages**\n\n## Best Practices Checklist\n\n- [ ] All images have descriptive alt text\n- [ ] Forms have associated labels\n- [ ] Interactive elements are keyboard accessible\n- [ ] Color contrast meets WCAG AA standards\n- [ ] ARIA attributes are used correctly\n- [ ] Focus indicators are visible\n- [ ] Error messages are clear and helpful\n- [ ] Content structure is logical and semantic\n- [ ] Page has a proper heading hierarchy\n- [ ] Skip navigation links are provided\n\n## Conclusion\n\nBuilding accessible web applications requires intentionality and ongoing effort, but the result is a better experience for all users. Start with semantic HTML, test regularly, and iterate based on user feedback.\n\nRemember: Accessibility is not a feature—it's a fundamental aspect of quality web development.\n\n---\n\n**About the Author**: Luis Bonilla is a Software Engineer and Technical Lead passionate about creating inclusive digital experiences that work for everyone.","src/content/blog/building-accessible-web-applications.md","5ab18fbcf24a58b9",{html:137,metadata:138},"<h1 id=\"building-accessible-web-applications-a-practical-guide\">Building Accessible Web Applications: A Practical Guide</h1>\n<p><strong>Web accessibility (a11y) means designing and developing websites that can be used by everyone, including the 15% of the world’s population with disabilities (WHO, 2023)</strong>. Accessible web applications follow WCAG (Web Content Accessibility Guidelines) standards to ensure content is perceivable, operable, understandable, and robust for all users, regardless of their abilities or assistive technologies used.</p>\n<p>Web accessibility isn’t just a nice-to-have—it’s a fundamental requirement for creating inclusive digital experiences. This guide covers practical techniques for building accessible web applications.</p>\n<h2 id=\"understanding-web-accessibility\">Understanding Web Accessibility</h2>\n<p>Web accessibility (a11y) ensures that websites and applications can be used by everyone, including people with:</p>\n<ul>\n<li>Visual impairments</li>\n<li>Hearing impairments</li>\n<li>Motor disabilities</li>\n<li>Cognitive disabilities</li>\n</ul>\n<h2 id=\"wcag-guidelines\">WCAG Guidelines</h2>\n<p>The Web Content Accessibility Guidelines (WCAG) provide a framework organized around four principles:</p>\n<h3 id=\"1-perceivable\">1. Perceivable</h3>\n<p>Information must be presentable to users in ways they can perceive.</p>\n<p><strong>Example</strong>: Provide text alternatives for images</p>\n<pre class=\"astro-code github-dark\" style=\"background-color:#24292e;color:#e1e4e8; overflow-x: auto;\" tabindex=\"0\" data-language=\"html\"><code><span class=\"line\"><span style=\"color:#E1E4E8\">&#x3C;</span><span style=\"color:#85E89D\">img</span><span style=\"color:#E1E4E8\"> </span></span>\n<span class=\"line\"><span style=\"color:#B392F0\">  src</span><span style=\"color:#E1E4E8\">=</span><span style=\"color:#9ECBFF\">\"chart.png\"</span><span style=\"color:#E1E4E8\"> </span></span>\n<span class=\"line\"><span style=\"color:#B392F0\">  alt</span><span style=\"color:#E1E4E8\">=</span><span style=\"color:#9ECBFF\">\"Sales growth chart showing 25% increase in Q3\"</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">/></span></span></code></pre>\n<h3 id=\"2-operable\">2. Operable</h3>\n<p>User interface components must be operable by all users.</p>\n<p><strong>Example</strong>: Ensure keyboard accessibility</p>\n<pre class=\"astro-code github-dark\" style=\"background-color:#24292e;color:#e1e4e8; overflow-x: auto;\" tabindex=\"0\" data-language=\"javascript\"><code><span class=\"line\"><span style=\"color:#6A737D\">// Good: Keyboard-accessible button</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">&#x3C;</span><span style=\"color:#85E89D\">button</span><span style=\"color:#E1E4E8\"> </span></span>\n<span class=\"line\"><span style=\"color:#B392F0\">  onClick</span><span style=\"color:#F97583\">=</span><span style=\"color:#E1E4E8\">{handleClick}</span></span>\n<span class=\"line\"><span style=\"color:#B392F0\">  onKeyPress</span><span style=\"color:#F97583\">=</span><span style=\"color:#E1E4E8\">{(</span><span style=\"color:#FFAB70\">e</span><span style=\"color:#E1E4E8\">) </span><span style=\"color:#F97583\">=></span><span style=\"color:#E1E4E8\"> e.key </span><span style=\"color:#F97583\">===</span><span style=\"color:#9ECBFF\"> 'Enter'</span><span style=\"color:#F97583\"> &#x26;&#x26;</span><span style=\"color:#B392F0\"> handleClick</span><span style=\"color:#E1E4E8\">()}</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">></span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  Submit</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">&#x3C;/</span><span style=\"color:#85E89D\">button</span><span style=\"color:#E1E4E8\">></span></span></code></pre>\n<h3 id=\"3-understandable\">3. Understandable</h3>\n<p>Information and interface operation must be understandable.</p>\n<p><strong>Example</strong>: Provide clear error messages</p>\n<pre class=\"astro-code github-dark\" style=\"background-color:#24292e;color:#e1e4e8; overflow-x: auto;\" tabindex=\"0\" data-language=\"html\"><code><span class=\"line\"><span style=\"color:#E1E4E8\">&#x3C;</span><span style=\"color:#85E89D\">input</span><span style=\"color:#E1E4E8\"> </span></span>\n<span class=\"line\"><span style=\"color:#B392F0\">  type</span><span style=\"color:#E1E4E8\">=</span><span style=\"color:#9ECBFF\">\"email\"</span><span style=\"color:#E1E4E8\"> </span></span>\n<span class=\"line\"><span style=\"color:#B392F0\">  aria-describedby</span><span style=\"color:#E1E4E8\">=</span><span style=\"color:#9ECBFF\">\"email-error\"</span></span>\n<span class=\"line\"><span style=\"color:#B392F0\">  required</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">/></span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">&#x3C;</span><span style=\"color:#85E89D\">span</span><span style=\"color:#B392F0\"> id</span><span style=\"color:#E1E4E8\">=</span><span style=\"color:#9ECBFF\">\"email-error\"</span><span style=\"color:#B392F0\"> role</span><span style=\"color:#E1E4E8\">=</span><span style=\"color:#9ECBFF\">\"alert\"</span><span style=\"color:#E1E4E8\">></span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  Please enter a valid email address</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">&#x3C;/</span><span style=\"color:#85E89D\">span</span><span style=\"color:#E1E4E8\">></span></span></code></pre>\n<h3 id=\"4-robust\">4. Robust</h3>\n<p>Content must be robust enough to work with various technologies.</p>\n<h2 id=\"practical-accessibility-techniques\">Practical Accessibility Techniques</h2>\n<h3 id=\"semantic-html\">Semantic HTML</h3>\n<p>Use appropriate HTML elements for their intended purpose:</p>\n<pre class=\"astro-code github-dark\" style=\"background-color:#24292e;color:#e1e4e8; overflow-x: auto;\" tabindex=\"0\" data-language=\"html\"><code><span class=\"line\"><span style=\"color:#6A737D\">&#x3C;!-- Good --></span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">&#x3C;</span><span style=\"color:#85E89D\">nav</span><span style=\"color:#E1E4E8\">></span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  &#x3C;</span><span style=\"color:#85E89D\">ul</span><span style=\"color:#E1E4E8\">></span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">    &#x3C;</span><span style=\"color:#85E89D\">li</span><span style=\"color:#E1E4E8\">>&#x3C;</span><span style=\"color:#85E89D\">a</span><span style=\"color:#B392F0\"> href</span><span style=\"color:#E1E4E8\">=</span><span style=\"color:#9ECBFF\">\"#home\"</span><span style=\"color:#E1E4E8\">>Home&#x3C;/</span><span style=\"color:#85E89D\">a</span><span style=\"color:#E1E4E8\">>&#x3C;/</span><span style=\"color:#85E89D\">li</span><span style=\"color:#E1E4E8\">></span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">    &#x3C;</span><span style=\"color:#85E89D\">li</span><span style=\"color:#E1E4E8\">>&#x3C;</span><span style=\"color:#85E89D\">a</span><span style=\"color:#B392F0\"> href</span><span style=\"color:#E1E4E8\">=</span><span style=\"color:#9ECBFF\">\"#about\"</span><span style=\"color:#E1E4E8\">>About&#x3C;/</span><span style=\"color:#85E89D\">a</span><span style=\"color:#E1E4E8\">>&#x3C;/</span><span style=\"color:#85E89D\">li</span><span style=\"color:#E1E4E8\">></span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  &#x3C;/</span><span style=\"color:#85E89D\">ul</span><span style=\"color:#E1E4E8\">></span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">&#x3C;/</span><span style=\"color:#85E89D\">nav</span><span style=\"color:#E1E4E8\">></span></span>\n<span class=\"line\"></span>\n<span class=\"line\"><span style=\"color:#6A737D\">&#x3C;!-- Avoid --></span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">&#x3C;</span><span style=\"color:#85E89D\">div</span><span style=\"color:#B392F0\"> class</span><span style=\"color:#E1E4E8\">=</span><span style=\"color:#9ECBFF\">\"nav\"</span><span style=\"color:#E1E4E8\">></span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  &#x3C;</span><span style=\"color:#85E89D\">span</span><span style=\"color:#B392F0\"> onclick</span><span style=\"color:#E1E4E8\">=</span><span style=\"color:#9ECBFF\">\"</span><span style=\"color:#B392F0\">navigate</span><span style=\"color:#9ECBFF\">()\"</span><span style=\"color:#E1E4E8\">>Home&#x3C;/</span><span style=\"color:#85E89D\">span</span><span style=\"color:#E1E4E8\">></span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">&#x3C;/</span><span style=\"color:#85E89D\">div</span><span style=\"color:#E1E4E8\">></span></span></code></pre>\n<h3 id=\"aria-attributes\">ARIA Attributes</h3>\n<p>Use ARIA attributes to enhance accessibility when semantic HTML isn’t sufficient:</p>\n<pre class=\"astro-code github-dark\" style=\"background-color:#24292e;color:#e1e4e8; overflow-x: auto;\" tabindex=\"0\" data-language=\"html\"><code><span class=\"line\"><span style=\"color:#E1E4E8\">&#x3C;</span><span style=\"color:#85E89D\">button</span><span style=\"color:#E1E4E8\"> </span></span>\n<span class=\"line\"><span style=\"color:#B392F0\">  aria-label</span><span style=\"color:#E1E4E8\">=</span><span style=\"color:#9ECBFF\">\"Close dialog\"</span></span>\n<span class=\"line\"><span style=\"color:#B392F0\">  aria-pressed</span><span style=\"color:#E1E4E8\">=</span><span style=\"color:#9ECBFF\">\"false\"</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">></span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  &#x3C;</span><span style=\"color:#85E89D\">span</span><span style=\"color:#B392F0\"> aria-hidden</span><span style=\"color:#E1E4E8\">=</span><span style=\"color:#9ECBFF\">\"true\"</span><span style=\"color:#E1E4E8\">>×&#x3C;/</span><span style=\"color:#85E89D\">span</span><span style=\"color:#E1E4E8\">></span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">&#x3C;/</span><span style=\"color:#85E89D\">button</span><span style=\"color:#E1E4E8\">></span></span></code></pre>\n<h3 id=\"focus-management\">Focus Management</h3>\n<p>Ensure visible focus indicators and logical focus order:</p>\n<pre class=\"astro-code github-dark\" style=\"background-color:#24292e;color:#e1e4e8; overflow-x: auto;\" tabindex=\"0\" data-language=\"css\"><code><span class=\"line\"><span style=\"color:#6A737D\">/* Visible focus indicator */</span></span>\n<span class=\"line\"><span style=\"color:#85E89D\">button</span><span style=\"color:#B392F0\">:focus-visible</span><span style=\"color:#E1E4E8\"> {</span></span>\n<span class=\"line\"><span style=\"color:#79B8FF\">  outline</span><span style=\"color:#E1E4E8\">: </span><span style=\"color:#79B8FF\">2</span><span style=\"color:#F97583\">px</span><span style=\"color:#79B8FF\"> solid</span><span style=\"color:#79B8FF\"> #007bff</span><span style=\"color:#E1E4E8\">;</span></span>\n<span class=\"line\"><span style=\"color:#79B8FF\">  outline-offset</span><span style=\"color:#E1E4E8\">: </span><span style=\"color:#79B8FF\">2</span><span style=\"color:#F97583\">px</span><span style=\"color:#E1E4E8\">;</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">}</span></span></code></pre>\n<h3 id=\"color-contrast\">Color Contrast</h3>\n<p>Maintain sufficient color contrast (WCAG AA: 4.5:1 for normal text):</p>\n<pre class=\"astro-code github-dark\" style=\"background-color:#24292e;color:#e1e4e8; overflow-x: auto;\" tabindex=\"0\" data-language=\"css\"><code><span class=\"line\"><span style=\"color:#6A737D\">/* Good contrast */</span></span>\n<span class=\"line\"><span style=\"color:#B392F0\">.text</span><span style=\"color:#E1E4E8\"> {</span></span>\n<span class=\"line\"><span style=\"color:#79B8FF\">  color</span><span style=\"color:#E1E4E8\">: </span><span style=\"color:#79B8FF\">#212529</span><span style=\"color:#E1E4E8\">;  </span><span style=\"color:#6A737D\">/* Dark gray */</span></span>\n<span class=\"line\"><span style=\"color:#79B8FF\">  background</span><span style=\"color:#E1E4E8\">: </span><span style=\"color:#79B8FF\">#ffffff</span><span style=\"color:#E1E4E8\">;  </span><span style=\"color:#6A737D\">/* White */</span></span>\n<span class=\"line\"><span style=\"color:#6A737D\">  /* Contrast ratio: 16.1:1 */</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">}</span></span></code></pre>\n<h2 id=\"testing-accessibility\">Testing Accessibility</h2>\n<h3 id=\"automated-testing\">Automated Testing</h3>\n<p>Use tools like:</p>\n<ul>\n<li><strong>axe DevTools</strong>: Browser extension for automated testing</li>\n<li><strong>Lighthouse</strong>: Built into Chrome DevTools</li>\n<li><strong>WAVE</strong>: Web accessibility evaluation tool</li>\n</ul>\n<h3 id=\"manual-testing\">Manual Testing</h3>\n<ol>\n<li><strong>Keyboard Navigation</strong>: Navigate using only keyboard (Tab, Enter, Escape)</li>\n<li><strong>Screen Reader Testing</strong>: Test with NVDA, JAWS, or VoiceOver</li>\n<li><strong>Zoom Testing</strong>: Test at 200% zoom level</li>\n<li><strong>Color Contrast</strong>: Use contrast checking tools</li>\n</ol>\n<h2 id=\"common-accessibility-pitfalls\">Common Accessibility Pitfalls</h2>\n<ol>\n<li><strong>Missing alt text</strong> on images</li>\n<li><strong>Poor focus management</strong> in modals and dialogs</li>\n<li><strong>Insufficient color contrast</strong></li>\n<li><strong>Missing form labels</strong></li>\n<li><strong>Keyboard traps</strong> in interactive components</li>\n<li><strong>Unclear error messages</strong></li>\n</ol>\n<h2 id=\"best-practices-checklist\">Best Practices Checklist</h2>\n<ul class=\"contains-task-list\">\n<li class=\"task-list-item\"><input type=\"checkbox\" disabled> All images have descriptive alt text</li>\n<li class=\"task-list-item\"><input type=\"checkbox\" disabled> Forms have associated labels</li>\n<li class=\"task-list-item\"><input type=\"checkbox\" disabled> Interactive elements are keyboard accessible</li>\n<li class=\"task-list-item\"><input type=\"checkbox\" disabled> Color contrast meets WCAG AA standards</li>\n<li class=\"task-list-item\"><input type=\"checkbox\" disabled> ARIA attributes are used correctly</li>\n<li class=\"task-list-item\"><input type=\"checkbox\" disabled> Focus indicators are visible</li>\n<li class=\"task-list-item\"><input type=\"checkbox\" disabled> Error messages are clear and helpful</li>\n<li class=\"task-list-item\"><input type=\"checkbox\" disabled> Content structure is logical and semantic</li>\n<li class=\"task-list-item\"><input type=\"checkbox\" disabled> Page has a proper heading hierarchy</li>\n<li class=\"task-list-item\"><input type=\"checkbox\" disabled> Skip navigation links are provided</li>\n</ul>\n<h2 id=\"conclusion\">Conclusion</h2>\n<p>Building accessible web applications requires intentionality and ongoing effort, but the result is a better experience for all users. Start with semantic HTML, test regularly, and iterate based on user feedback.</p>\n<p>Remember: Accessibility is not a feature—it’s a fundamental aspect of quality web development.</p>\n<hr>\n<p><strong>About the Author</strong>: Luis Bonilla is a Software Engineer and Technical Lead passionate about creating inclusive digital experiences that work for everyone.</p>",{headings:139,localImagePaths:189,remoteImagePaths:190,frontmatter:191,imagePaths:196},[140,142,145,148,151,154,157,160,163,166,169,172,175,178,181,184,187,188],{depth:39,slug:141,text:121},"building-accessible-web-applications-a-practical-guide",{depth:42,slug:143,text:144},"understanding-web-accessibility","Understanding Web Accessibility",{depth:42,slug:146,text:147},"wcag-guidelines","WCAG Guidelines",{depth:46,slug:149,text:150},"1-perceivable","1. Perceivable",{depth:46,slug:152,text:153},"2-operable","2. Operable",{depth:46,slug:155,text:156},"3-understandable","3. Understandable",{depth:46,slug:158,text:159},"4-robust","4. Robust",{depth:42,slug:161,text:162},"practical-accessibility-techniques","Practical Accessibility Techniques",{depth:46,slug:164,text:165},"semantic-html","Semantic HTML",{depth:46,slug:167,text:168},"aria-attributes","ARIA Attributes",{depth:46,slug:170,text:171},"focus-management","Focus Management",{depth:46,slug:173,text:174},"color-contrast","Color Contrast",{depth:42,slug:176,text:177},"testing-accessibility","Testing Accessibility",{depth:46,slug:179,text:180},"automated-testing","Automated Testing",{depth:46,slug:182,text:183},"manual-testing","Manual Testing",{depth:42,slug:185,text:186},"common-accessibility-pitfalls","Common Accessibility Pitfalls",{depth:42,slug:104,text:105},{depth:42,slug:107,text:108},[],[],{title:121,description:122,pubDate:192,author:17,tags:193,lang:24,draft:25,jsonLd:194},["Date","2024-10-10T00:00:00.000Z"],[125,126,127,128,129],{type:27,headline:121,description:122,author:195,datePublished:132},{type:29,name:17},[],"building-accessible-web-applications.md","getting-started-with-astro",{id:198,data:200,body:211,filePath:212,digest:213,rendered:214,legacyId:250},{title:201,description:202,pubDate:203,author:17,tags:204,lang:24,draft:25,jsonLd:208},"Getting Started with Astro: A Modern Static Site Generator","Explore Astro, a modern static site generator that delivers lightning-fast performance with zero JavaScript by default.",["Date","2024-10-14T00:00:00.000Z"],[205,127,206,207],"astro","static-site-generator","performance",{type:27,headline:201,description:202,author:209,datePublished:210},{type:29,name:17},"2024-10-14","# Getting Started with Astro: A Modern Static Site Generator\n\n**Astro is a modern static site generator that delivers lightning-fast performance by shipping zero JavaScript by default**. Unlike traditional frameworks, Astro uses an \"island architecture\" that lets you build fast websites with minimal client-side JavaScript while still using your favorite UI frameworks (React, Vue, Svelte) where needed.\n\nAstro has emerged as a game-changer in the world of static site generators. With its unique approach to web development, it combines the best of modern frameworks while delivering exceptional performance.\n\n## Why Astro?\n\nAstro stands out for several compelling reasons:\n\n1. **Zero JavaScript by Default**: Astro ships zero JavaScript to the browser by default, resulting in blazing-fast load times.\n2. **Component Islands**: Use your favorite frameworks (React, Vue, Svelte) only where you need them.\n3. **Built-in Optimization**: Automatic image optimization, CSS bundling, and more.\n4. **Developer Experience**: Intuitive file-based routing and component architecture.\n\n## Key Features\n\n### Partial Hydration\n\nAstro pioneered the concept of \"partial hydration\" or \"island architecture.\" This allows you to use interactive components only where needed:\n\n```astro\n---\nimport InteractiveWidget from '../components/InteractiveWidget.jsx';\n---\n\n<div>\n  <h1>Welcome to my site</h1>\n  <!-- This component will be interactive on the client -->\n  <InteractiveWidget client:load />\n</div>\n```\n\n### Content Collections\n\nAstro's content collections provide type-safe content management with built-in validation:\n\n```typescript\nimport { defineCollection, z } from 'astro:content';\n\nconst blog = defineCollection({\n  schema: z.object({\n    title: z.string(),\n    pubDate: z.date(),\n    description: z.string(),\n  }),\n});\n```\n\n## Performance Benefits\n\nBy shipping minimal JavaScript, Astro sites achieve:\n\n- **Faster Page Loads**: Less code to download and parse\n- **Better SEO**: Search engines love fast sites\n- **Improved Core Web Vitals**: Better scores on performance metrics\n- **Enhanced User Experience**: Instant page transitions\n\n## Getting Started\n\nTo create a new Astro project:\n\n```bash\nnpm create astro@latest\ncd my-astro-project\nnpm run dev\n```\n\n## Conclusion\n\nAstro represents a paradigm shift in web development, prioritizing performance without sacrificing developer experience. Whether you're building a blog, documentation site, or portfolio, Astro provides the tools to create fast, modern web experiences.\n\n## Frequently Asked Questions\n\n**Q: What is Astro's main advantage over other static site generators?**  \nA: Astro's main advantage is its zero-JavaScript-by-default approach combined with island architecture, resulting in significantly faster load times and better Core Web Vitals scores compared to traditional SPAs.\n\n**Q: Can I use React, Vue, or Svelte components with Astro?**  \nA: Yes, Astro supports multiple frameworks through its island architecture. You can use interactive components from React, Vue, Svelte, and other frameworks selectively where you need interactivity.\n\n**Q: Is Astro suitable for dynamic websites or only static sites?**  \nA: While Astro excels at static sites, it also supports Server-Side Rendering (SSR) and can handle dynamic content through API routes and server endpoints.\n\n**Q: How does Astro compare to Next.js or Gatsby?**  \nA: Astro focuses on shipping minimal JavaScript (0 KB by default), while Next.js and Gatsby ship full framework bundles. Astro is typically faster for content-heavy sites, while Next.js may be better for highly interactive applications.\n\n**Q: What kind of websites is Astro best for?**  \nA: Astro is ideal for content-focused sites like blogs, documentation, portfolios, marketing sites, and any project where performance and SEO are priorities.\n\n---\n\n**About the Author**: Luis Bonilla is a Software Engineer and Technical Lead with 15+ years of experience in web development and digital transformation.","src/content/blog/getting-started-with-astro.md","f7080202285c1c6e",{html:215,metadata:216},"<h1 id=\"getting-started-with-astro-a-modern-static-site-generator\">Getting Started with Astro: A Modern Static Site Generator</h1>\n<p><strong>Astro is a modern static site generator that delivers lightning-fast performance by shipping zero JavaScript by default</strong>. Unlike traditional frameworks, Astro uses an “island architecture” that lets you build fast websites with minimal client-side JavaScript while still using your favorite UI frameworks (React, Vue, Svelte) where needed.</p>\n<p>Astro has emerged as a game-changer in the world of static site generators. With its unique approach to web development, it combines the best of modern frameworks while delivering exceptional performance.</p>\n<h2 id=\"why-astro\">Why Astro?</h2>\n<p>Astro stands out for several compelling reasons:</p>\n<ol>\n<li><strong>Zero JavaScript by Default</strong>: Astro ships zero JavaScript to the browser by default, resulting in blazing-fast load times.</li>\n<li><strong>Component Islands</strong>: Use your favorite frameworks (React, Vue, Svelte) only where you need them.</li>\n<li><strong>Built-in Optimization</strong>: Automatic image optimization, CSS bundling, and more.</li>\n<li><strong>Developer Experience</strong>: Intuitive file-based routing and component architecture.</li>\n</ol>\n<h2 id=\"key-features\">Key Features</h2>\n<h3 id=\"partial-hydration\">Partial Hydration</h3>\n<p>Astro pioneered the concept of “partial hydration” or “island architecture.” This allows you to use interactive components only where needed:</p>\n<pre class=\"astro-code github-dark\" style=\"background-color:#24292e;color:#e1e4e8; overflow-x: auto;\" tabindex=\"0\" data-language=\"astro\"><code><span class=\"line\"><span style=\"color:#6A737D\">---</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">import</span><span style=\"color:#E1E4E8\"> InteractiveWidget </span><span style=\"color:#F97583\">from</span><span style=\"color:#9ECBFF\"> '../components/InteractiveWidget.jsx'</span><span style=\"color:#E1E4E8\">;</span></span>\n<span class=\"line\"><span style=\"color:#6A737D\">---</span></span>\n<span class=\"line\"></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">&#x3C;</span><span style=\"color:#85E89D\">div</span><span style=\"color:#E1E4E8\">></span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  &#x3C;</span><span style=\"color:#85E89D\">h1</span><span style=\"color:#E1E4E8\">>Welcome to my site&#x3C;/</span><span style=\"color:#85E89D\">h1</span><span style=\"color:#E1E4E8\">></span></span>\n<span class=\"line\"><span style=\"color:#6A737D\">  &#x3C;!-- This component will be interactive on the client --></span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  &#x3C;</span><span style=\"color:#79B8FF\">InteractiveWidget</span><span style=\"color:#B392F0\"> client:load</span><span style=\"color:#E1E4E8\"> /></span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">&#x3C;/</span><span style=\"color:#85E89D\">div</span><span style=\"color:#E1E4E8\">></span></span></code></pre>\n<h3 id=\"content-collections\">Content Collections</h3>\n<p>Astro’s content collections provide type-safe content management with built-in validation:</p>\n<pre class=\"astro-code github-dark\" style=\"background-color:#24292e;color:#e1e4e8; overflow-x: auto;\" tabindex=\"0\" data-language=\"typescript\"><code><span class=\"line\"><span style=\"color:#F97583\">import</span><span style=\"color:#E1E4E8\"> { defineCollection, z } </span><span style=\"color:#F97583\">from</span><span style=\"color:#9ECBFF\"> 'astro:content'</span><span style=\"color:#E1E4E8\">;</span></span>\n<span class=\"line\"></span>\n<span class=\"line\"><span style=\"color:#F97583\">const</span><span style=\"color:#79B8FF\"> blog</span><span style=\"color:#F97583\"> =</span><span style=\"color:#B392F0\"> defineCollection</span><span style=\"color:#E1E4E8\">({</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  schema: z.</span><span style=\"color:#B392F0\">object</span><span style=\"color:#E1E4E8\">({</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">    title: z.</span><span style=\"color:#B392F0\">string</span><span style=\"color:#E1E4E8\">(),</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">    pubDate: z.</span><span style=\"color:#B392F0\">date</span><span style=\"color:#E1E4E8\">(),</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">    description: z.</span><span style=\"color:#B392F0\">string</span><span style=\"color:#E1E4E8\">(),</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  }),</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">});</span></span></code></pre>\n<h2 id=\"performance-benefits\">Performance Benefits</h2>\n<p>By shipping minimal JavaScript, Astro sites achieve:</p>\n<ul>\n<li><strong>Faster Page Loads</strong>: Less code to download and parse</li>\n<li><strong>Better SEO</strong>: Search engines love fast sites</li>\n<li><strong>Improved Core Web Vitals</strong>: Better scores on performance metrics</li>\n<li><strong>Enhanced User Experience</strong>: Instant page transitions</li>\n</ul>\n<h2 id=\"getting-started\">Getting Started</h2>\n<p>To create a new Astro project:</p>\n<pre class=\"astro-code github-dark\" style=\"background-color:#24292e;color:#e1e4e8; overflow-x: auto;\" tabindex=\"0\" data-language=\"bash\"><code><span class=\"line\"><span style=\"color:#B392F0\">npm</span><span style=\"color:#9ECBFF\"> create</span><span style=\"color:#9ECBFF\"> astro@latest</span></span>\n<span class=\"line\"><span style=\"color:#79B8FF\">cd</span><span style=\"color:#9ECBFF\"> my-astro-project</span></span>\n<span class=\"line\"><span style=\"color:#B392F0\">npm</span><span style=\"color:#9ECBFF\"> run</span><span style=\"color:#9ECBFF\"> dev</span></span></code></pre>\n<h2 id=\"conclusion\">Conclusion</h2>\n<p>Astro represents a paradigm shift in web development, prioritizing performance without sacrificing developer experience. Whether you’re building a blog, documentation site, or portfolio, Astro provides the tools to create fast, modern web experiences.</p>\n<h2 id=\"frequently-asked-questions\">Frequently Asked Questions</h2>\n<p><strong>Q: What is Astro’s main advantage over other static site generators?</strong><br>\nA: Astro’s main advantage is its zero-JavaScript-by-default approach combined with island architecture, resulting in significantly faster load times and better Core Web Vitals scores compared to traditional SPAs.</p>\n<p><strong>Q: Can I use React, Vue, or Svelte components with Astro?</strong><br>\nA: Yes, Astro supports multiple frameworks through its island architecture. You can use interactive components from React, Vue, Svelte, and other frameworks selectively where you need interactivity.</p>\n<p><strong>Q: Is Astro suitable for dynamic websites or only static sites?</strong><br>\nA: While Astro excels at static sites, it also supports Server-Side Rendering (SSR) and can handle dynamic content through API routes and server endpoints.</p>\n<p><strong>Q: How does Astro compare to Next.js or Gatsby?</strong><br>\nA: Astro focuses on shipping minimal JavaScript (0 KB by default), while Next.js and Gatsby ship full framework bundles. Astro is typically faster for content-heavy sites, while Next.js may be better for highly interactive applications.</p>\n<p><strong>Q: What kind of websites is Astro best for?</strong><br>\nA: Astro is ideal for content-focused sites like blogs, documentation, portfolios, marketing sites, and any project where performance and SEO are priorities.</p>\n<hr>\n<p><strong>About the Author</strong>: Luis Bonilla is a Software Engineer and Technical Lead with 15+ years of experience in web development and digital transformation.</p>",{headings:217,localImagePaths:242,remoteImagePaths:243,frontmatter:244,imagePaths:249},[218,220,223,226,229,232,235,238,239],{depth:39,slug:219,text:201},"getting-started-with-astro-a-modern-static-site-generator",{depth:42,slug:221,text:222},"why-astro","Why Astro?",{depth:42,slug:224,text:225},"key-features","Key Features",{depth:46,slug:227,text:228},"partial-hydration","Partial Hydration",{depth:46,slug:230,text:231},"content-collections","Content Collections",{depth:42,slug:233,text:234},"performance-benefits","Performance Benefits",{depth:42,slug:236,text:237},"getting-started","Getting Started",{depth:42,slug:107,text:108},{depth:42,slug:240,text:241},"frequently-asked-questions","Frequently Asked Questions",[],[],{title:201,description:202,pubDate:245,author:17,tags:246,lang:24,draft:25,jsonLd:247},["Date","2024-10-14T00:00:00.000Z"],[205,127,206,207],{type:27,headline:201,description:202,author:248,datePublished:210},{type:29,name:17},[],"getting-started-with-astro.md"];

